{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-8cef35fbe5d93dc2","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Shared-surface enforcement deliverables: a general Implementation epic\n28\t     (null implementation_type) whose TITLE names an enforcement tool (lint\n29\t     rule, CI check, static-analysis check, validation harness, enforcement)\n30\t     that shares its `component` with at least one other non-docs\n31\t     Implementation epic is a work-type extraction — the enforcement work was\n32\t     divided by work-product type instead of per surface. Exempt when the\n33\t     enforcement tool is the component's only implementation work (it is then\n34\t     the deliverable itself, not an extraction).\n35\t\n36\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n37\t\n38\tUsage:\n39\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n40\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n41\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n42\t\"\"\"\n43\t\n44\timport argparse\n45\timport os\n46\timport re\n47\timport sys\n48\t\n49\timport yaml\n50\t\n51\tSECTIONS = [(\"Description\", (\"description\",)),\n52\t            (\"Scope\", (\"scope\",)),\n53\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n54\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n55\t\n56\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n57\t\n58\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n59\t           \"repo-onboarding\")\n60\t\n61\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n62\t# way) — parity with the implementation_type_rules judge.\n63\tPARALLEL_PAIRS = {\n64\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n65\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n66\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n67\t}\n68\t\n69\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n70\t\n71\t# An enforcement tool named in a general Implementation epic's TITLE — the\n72\t# signature of a work-type extraction of a shared-surface deliverable.\n73\tENFORCEMENT_TITLE_RE = re.compile(\n74\t    r'\\b(lint(?:er)? rule|ci check|static[- ]analysis|validation harness|'\n75\t    r'enforc\\w*)\\b', re.IGNORECASE)\n76\t\n77\t\n78\tdef read_frontmatter(path):\n79\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n80\t    with open(path, encoding=\"utf-8\") as f:\n81\t        content = f.read()\n82\t    m = FRONTMATTER_RE.match(content)\n83\t    if not m:\n84\t        return {}, content\n85\t    try:\n86\t        data = yaml.safe_load(m.group(1))\n87\t    except yaml.YAMLError:\n88\t        return {}, content\n89\t    if not isinstance(data, dict):\n90\t        return {}, content\n91\t    return data, content[m.end():]\n92\t\n93\t\n94\tdef body_headings(body):\n95\t    heads = []\n96\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n97\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n98\t    return heads\n99\t\n100\t\n101\tdef load_epics(artifacts_dir, strat_id):\n102\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n103\t\n104\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n105\t    \"\"\"\n106\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n107\t    if not os.path.isdir(task_dir):\n108\t        return {}\n109\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n110\t    epics = {}\n111\t    for name in sorted(os.listdir(task_dir)):\n112\t        m = pat.match(name)\n113\t        if not m:\n114\t            continue\n115\t        path = os.path.join(task_dir, name)\n116\t        fm, body = read_frontmatter(path)\n117\t        epics[name[:-3]] = (path, fm, body)\n118\t    return epics\n119\t\n120\t\n121\tdef dependency_closure(start_key, deps):\n122\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n123\t    seen, stack = set(), list(deps.get(start_key, []))\n124\t    while stack:\n125\t        n = stack.pop()\n126\t        if n in seen or n not in deps:\n127\t            continue\n128\t        seen.add(n)\n129\t        stack.extend(deps[n])\n130\t    return seen\n131\t\n132\t\n133\tdef check(strat_id, artifacts_dir, components_path):\n134\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n135\t    probs = []\n136\t    epics = load_epics(artifacts_dir, strat_id)\n137\t    if not epics:\n138\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n139\t                % (strat_id, artifacts_dir)]\n140\t\n141\t    valid_components = set()\n142\t    if os.path.isfile(components_path):\n143\t        with open(components_path, encoding=\"utf-8\") as f:\n144\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n145\t    if not valid_components:\n146\t        probs.append(\"cannot read canonical component list %s — verify the \"\n147\t                     \"path before trusting component names\" % components_path)\n148\t\n149\t    deps, is_branch, is_docs, is_impl, itype, prio, titles, comps = \\\n150\t        {}, {}, {}, {}, {}, {}, {}, {}\n151\t    for key, (path, fm, body) in epics.items():\n152\t        name = key + \".md\"\n153\t        # 1. body sections (contract parity with the artifact judge)\n154\t        heads = body_headings(body)\n155\t        for want, aliases in SECTIONS:\n156\t            if not any(a in h for h in heads for a in aliases):\n157\t                probs.append(\"%s: body missing '%s' section (required \"\n158\t                             \"sections: Description, Scope, Acceptance \"\n159\t                             \"Criteria, HLR Traceability)\" % (name, want))\n160\t        # 2. component vocabulary\n161\t        comp = fm.get(\"component\")\n162\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n163\t                and comp.strip() not in valid_components:\n164\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n165\t                         \"canonical name (submit.py strips unknown names)\"\n166\t                         % (name, comp.strip(), components_path))\n167\t        # collect graph facts\n168\t        dl = fm.get(\"dependencies\")\n169\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n170\t            if isinstance(dl, list) else []\n171\t        is_branch[key] = \"BRANCH-\" in key\n172\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n173\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n174\t        it = fm.get(\"implementation_type\")\n175\t        itype[key] = it if it in IT_ENUM else None\n176\t        prio[key] = fm.get(\"priority\")\n177\t        titles[key] = str(fm.get(\"title\") or \"\")\n178\t        comps[key] = str(comp).strip() if isinstance(comp, str) else None\n179\t\n180\t    def kind(key):\n181\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n182\t        that is not type Implementation is never a parallel-rule party; an\n183\t        Implementation epic's kind is its implementation_type when that is a\n184\t        known label, else 'general'.\"\"\"\n185\t        if not is_impl[key]:\n186\t            return \"non-implementation\"\n187\t        return itype[key] or \"general\"\n188\t\n189\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n190\t    universe = [k for k in epics\n191\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n192\t    for k in sorted(epics):\n193\t        if not is_docs[k]:\n194\t            continue\n195\t        cl = dependency_closure(k, deps)\n196\t        missing = sorted(e for e in universe if e != k and e not in cl)\n197\t        if missing:\n198\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n199\t                         \"Implementation epic — add %s to its dependency chain\"\n200\t                         % (k, \", \".join(missing)))\n201\t\n202\t    # 4. Priority inheritance — enablers of P0 work must be P0\n203\t    for k in sorted(epics):\n204\t        if is_branch[k] or is_docs[k]:\n205\t            continue\n206\t        if prio.get(k) != \"P0\":\n207\t            continue\n208\t        # every main-plan, non-docs epic in k's closure enables P0 work\n209\t        cl = dependency_closure(k, deps)\n210\t        for t in sorted(cl):\n211\t            if is_branch[t] or is_docs[t]:\n212\t                continue\n213\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n214\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n215\t                             \"but is %s — raise it to P0 or restructure\"\n216\t                             % (t, prio.get(t), k, prio.get(t)))\n217\t\n218\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n219\t    #    pairs carry no dependencies edge in either direction (direct edges\n220\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n221\t    #    them; dependencies naming epics with no file cannot be judged).\n222\t    for k in sorted(epics):\n223\t        if kind(k) == \"docs-authoring\":\n224\t            continue\n225\t        for t in deps[k]:\n226\t            if t not in epics:\n227\t                continue\n228\t            pair = frozenset((kind(t), kind(k)))\n229\t            rule = PARALLEL_PAIRS.get(pair)\n230\t            if rule:\n231\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n232\t                             \"parallel; remove the dependencies edge and \"\n233\t                             \"express any coupling as an AC gate on the \"\n234\t                             \"dependent epic\"\n235\t                             % (rule, t, kind(t), k, kind(k)))\n236\t\n237\t    # 6. Shared-surface enforcement deliverable — a general Implementation\n238\t    #    epic whose title names an enforcement tool AND shares its component\n239\t    #    with another non-docs Implementation epic is a work-type extraction:\n240\t    #    the enforcement work must be divided per surface into the consuming\n241\t    #    epics, not carved into a standalone work-type epic. Exempt when the\n242\t    #    enforcement tool is the component's only implementation work.\n243\t    impl_keys = sorted(k for k in epics\n244\t                       if is_impl[k] and not is_branch[k] and not is_docs[k])\n245\t    for k in impl_keys:\n246\t        if itype[k] is not None:  # routed labels are never the extraction\n247\t            continue\n248\t        if not ENFORCEMENT_TITLE_RE.search(titles[k]):\n249\t            continue\n250\t        siblings = [j for j in impl_keys\n251\t                    if j != k and comps[j] and comps[j] == comps[k]]\n252\t        if not siblings:\n253\t            continue\n254\t        probs.append(\"%s: standalone enforcement deliverable — an enforcement \"\n255\t                     \"tool ('%s') shared with other implementation work in \"\n256\t                     \"the same component must be divided per surface into \"\n257\t                     \"each consuming epic's Scope and Acceptance Criteria, \"\n258\t                     \"not extracted into a work-type epic; FIX: fold the \"\n259\t                     \"enforcement work back into every epic whose surface it \"\n260\t                     \"covers (as scope + a verification AC), delete this \"\n261\t                     \"epic, and update the summary's Epic List, DAG diagram \"\n262\t                     \"and traceability matrix\"\n263\t                     % (k + \".md\", titles[k]))\n264\t    return probs\n265\t\n266\t\n267\t# ─── self-check ───────────────────────────────────────────────────────────────\n268\t\n269\tdef _self_check():\n270\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n271\t    import shutil\n272\t    import tempfile\n273\t\n274\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n275\t    try:\n276\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n277\t        os.makedirs(art)\n278\t        comp = os.path.join(tmp, \"components.txt\")\n279\t        with open(comp, \"w\") as f:\n280\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n281\t\n282\t        def write(name, fm, body):\n283\t            with open(os.path.join(art, name), \"w\") as f:\n284\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n285\t\n286\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n287\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n288\t        write(\"RHAISTRAT-9001-E001.md\",\n289\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n290\t              \"dependencies: []\\n\", good_body)\n291\t        write(\"RHAISTRAT-9001-E002.md\",\n292\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n293\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n294\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n295\t              good_body)\n296\t        # a konflux-onboarding epic parallel to the general epic (no edge\n297\t        # either way) is the Rule 10-compliant shape — must not be flagged\n298\t        write(\"RHAISTRAT-9001-E003.md\",\n299\t              \"component: Dashboard\\ntype: Implementation\\n\"\n300\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n301\t              \"dependencies: []\\n\", good_body)\n302\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n303\t                     comp) == [], \"good fixture must pass cleanly\"\n304\t\n305\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n306\t        # Rule 10 konflux-onboarding -> general edge\n307\t        write(\"RHAISTRAT-9002-E001.md\",\n308\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n309\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n310\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n311\t              \"## HLR Traceability\\nh\\n\")\n312\t        write(\"RHAISTRAT-9002-E002.md\",\n313\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n314\t              \"dependencies: []\\n\", good_body)\n315\t        write(\"RHAISTRAT-9002-E003.md\",\n316\t              \"component: Dashboard\\ntype: Implementation\\n\"\n317\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n318\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n319\t        # E004 is a main-plan Implementation the docs epic never depends on\n320\t        write(\"RHAISTRAT-9002-E004.md\",\n321\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n322\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n323\t        write(\"RHAISTRAT-9002-E005.md\",\n324\t              \"component: Dashboard\\ntype: Implementation\\n\"\n325\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n326\t              \"dependencies: []\\n\", good_body)\n327\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n328\t        joined = \"\\n\".join(probs)\n329\t        assert \"missing 'Scope'\" in joined, probs\n330\t        assert \"Model Serving Stack\" in joined, probs\n331\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n332\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n333\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n334\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n335\t\n336\t        # check 6 — work-type extraction of a shared-surface enforcement\n337\t        # deliverable: bad shape (standalone lint-rule epic sharing the\n338\t        # component with two other general Implementation epics) vs. the two\n339\t        # exempt shapes (enforcement tool as the component's only\n340\t        # implementation work; per-surface division — no standalone epic).\n341\t        write(\"RHAISTRAT-9003-E001.md\",\n342\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n343\t              \"title: Convert manager binary log calls\\n\"\n344\t              \"dependencies: []\\n\", good_body)\n345\t        write(\"RHAISTRAT-9003-E002.md\",\n346\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n347\t              \"title: Convert cloudmanager binary log calls\\n\"\n348\t              \"dependencies: []\\n\", good_body)\n349\t        write(\"RHAISTRAT-9003-E003.md\",\n350\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n351\t              \"title: CI lint rule enforcing structured log fields\\n\"\n352\t              \"dependencies: []\\n\", good_body)\n353\t        probs3 = check(\"RHAISTRAT-9003\", os.path.join(tmp, \"artifacts\"), comp)\n354\t        c6 = [p for p in probs3 if \"standalone enforcement deliverable\" in p]\n355\t        assert len(c6) == 1 and \"RHAISTRAT-9003-E003.md\" in c6[0], probs3\n356\t        # exemption: enforcement tool is the component's only implementation\n357\t        # work — the deliverable itself, not an extraction\n358\t        write(\"RHAISTRAT-9004-E001.md\",\n359\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n360\t              \"priority: P0\\ntitle: Repo-wide lint rule for API docs\\n\"\n361\t              \"dependencies: []\\n\", good_body)\n362\t        assert check(\"RHAISTRAT-9004\", os.path.join(tmp, \"artifacts\"),\n363\t                     comp) == [], \"lone enforcement epic must pass cleanly\"\n364\t        print(\"self-check OK: 6 checks fire on bad fixture, clean on good\")\n365\t        return 0\n366\t    finally:\n367\t        shutil.rmtree(tmp, ignore_errors=True)\n368\t\n369\t\n370\tdef main(argv=None):\n371\t    ap = argparse.ArgumentParser(description=__doc__)\n372\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n373\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n374\t    ap.add_argument(\"--components\",\n375\t                    default=\".context/rhai-components.txt\")\n376\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n377\t    args = ap.parse_args(argv)\n378\t\n379\t    if args.self_check:\n380\t        return _self_check()\n381\t    if not args.strat_id:\n382\t        ap.error(\"strat_id is required (unless --self-check)\")\n383\t\n384\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n385\t    if probs:\n386\t        for p in probs:\n387\t            print(\"VIOLATION: %s\" % p)\n388\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n389\t              \"complete\" % len(probs))\n390\t        return 1\n391\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n392\t    return 0\n393\t\n394\t\n395\tif __name__ == \"__main__\":\n396\t    sys.exit(main())\n397\t"}]},"parent_tool_use_id":"chatcmpl-tool-846eb023bd761b18","agent_id":"a752c525d87d20bde","session_id":"b04d48ec-e92b-4b9b-98a0-90c74f405f25","uuid":"041b2779-94a6-4727-9f0c-77cccd23baaf","timestamp":"2026-10-26T18:55:03.012Z","tool_result_meta":[{"id":"chatcmpl-tool-8cef35fbe5d93dc2","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-9013"}
